// ── Validate and extract input ──────────────────────
const body = $input.first().json.body || $input.first().json;

const target = (body.target || body.url || body.domain || body.ip || '').trim();
const type   = (body.type || '').trim().toLowerCase();

if (!target) {
  throw new Error('Missing field: target (url/domain/ip)');
}

// Auto-detect type if not provided
let scanType = type;
if (!scanType) {
  if (/^\d{1,3}(\.\d{1,3}){3}$/.test(target)) {
    scanType = 'ip';
  } else {
    scanType = 'domain';
  }
}

// Clean domain — strip http/https/www/paths
let cleanTarget = target;
if (scanType === 'domain') {
  cleanTarget = target
    .replace(/^https?:\/\//i, '')
    .replace(/^www\./i, '')
    .split('/')[0]
    .split('?')[0]
    .trim();
}

return [{
  json: {
    target:       cleanTarget,
    original:     target,
    type:         scanType,
    triggered_at: new Date().toISOString(),
    api_base:     'YOUR_API_BASE_URL',
    api_secret:   'darkweb_secret_2024'
  }
}];

const scan = $input.first().json;

const threatLevel = scan.threat_level || 'UNKNOWN';
const aiAnalysis  = scan.ai_analysis  || 'No analysis';
const scanId      = scan.scan_id      || 'N/A';

const summaryLine = aiAnalysis
  .split('\n')
  .map(l => l.replace(/\*\*/g, '').trim())
  .find(l => l.length > 20 && !l.includes('THREAT SUMMARY'))
  || aiAnalysis.slice(0, 200);

return [{
  json: {
    status:       'complete',
    scan_id:      scanId,
    target:       scan.target       || 'N/A',
    target_type:  scan.target_type  || 'N/A',
    threat_level: threatLevel,
    summary:      summaryLine,
    ai_analysis:  aiAnalysis,
    alerts_sent:  scan.alerts_sent  || {},
    pdf_url:      scan.pdf_url      || null,
    completed_at: scan.completed_at || new Date().toISOString()
  }
}];
